steps.command:
perl -e 'my $pid = fork();
if ($pid == 0) { sleep 30; exit 0 }
sleep 1;
open(my $mp, "<", "/proc/$pid/maps") or die;
my $start;
while (<$mp>) { if (/^([0-9a-f]+)-\S+\s+rw/) { $start = hex($1); last } }
die "쓰기 가능한 구간 없음\n" unless defined $start;
open(my $m, "+<", "/proc/$pid/mem") or die "mem 열기 실패: $!\n";
seek($m, $start, 0) or die "seek 실패: $!\n";
read($m, my $b, 1) == 1 or die "read 실패: $!\n";
seek($m, $start, 0);
print {$m} $b or die "write 실패: $!\n";
close $m; kill 9, $pid;
print "proc mem 쓰기 완료\n";'
